<script setup>
import {ownerDate,ownerStayEnd,ownerBookingReference,ownerUpfrontPayment,ownerBookingStage,ownerTimestamp} from '../utils/ownerBookingDisplay.js';
import UserAvatar from './UserAvatar.vue';
import {paymentException} from '../utils/paidReservationPolicy.js';
import {badgeIcon} from '../utils/badgeIcons.js';
import '../styles/owner-badges.css';
defineProps({bookings:{type:Array,default:()=>[]}});
const pendingCancellation=b=>{try{return JSON.parse(b.cancellation_review || 'null')?.status==='pending';}catch{return false;}};
const nextStep=b=>paymentException(b) ? 'Payment received but it did not secure this reservation, so no bed is held. The platform cannot cancel or refund it; settle it with the student outside the platform.' : b.occupancy_start_issue ? b.occupancy_start_issue : b.payment_method==='paymongo' && ownerUpfrontPayment(b).key!=='paid' ? 'Waiting for the student to pay online. The reservation may expire if the payment deadline passes.' : b.payment_method==='cash' ? (ownerUpfrontPayment(b).key==='paid' ? 'Cash collection recorded. Confirm arrival when the student moves in.' : 'Cash is due at move-in. Record collection and confirm arrival when the student arrives.') : 'Upfront payment received. Confirm arrival when the student moves in.';
const bookingLink=b=>({path:'/owner/bookings',query:{houseId:String(b.house_id),bookingId:String(b.id)}});
</script>
<template>
<section v-if="bookings.length" class="upcoming" aria-labelledby="upcoming-heading">
<header class="upcoming-heading"><h2 id="upcoming-heading"><i class="fa-regular fa-calendar-days" aria-hidden="true"></i>Upcoming reservations <span class="upcoming-count">{{ bookings.length }}</span></h2><p>Upcoming stays are listed by their booked dates, separately from today's assigned beds.</p></header>
<div class="upcoming-list"><article v-for="b in bookings" :key="b.id" class="upcoming-card">
<div class="upcoming-identity"><UserAvatar :src="b.profile_pic" :name="b.student_name" class="upcoming-avatar" /><div><h3>{{ b.student_name }}</h3><span class="upcoming-ref">{{ ownerBookingReference(b) }}</span></div><span :class="['o-badge',ownerBookingStage(b).tone]"><i :class="['fa-solid',badgeIcon(ownerBookingStage(b))]" aria-hidden="true"></i>{{ ownerBookingStage(b).label }}</span></div>
<dl class="upcoming-facts"><div><dt>Check-in</dt><dd>{{ ownerDate(b.check_in_date) }}</dd></div><div><dt>Check-out</dt><dd>{{ ownerDate(ownerStayEnd(b)) }}</dd></div><div><dt>Move-in payment</dt><dd><span :class="['o-badge','payment',ownerUpfrontPayment(b).tone]"><i :class="['fa-solid',b.payment_method==='cash' ? 'fa-money-bill-wave' : 'fa-credit-card']" aria-hidden="true"></i>{{ b.payment_method==='cash' && ownerUpfrontPayment(b).key!=='paid' ? 'Cash due at move-in' : ownerUpfrontPayment(b).key==='paid' ? (b.payment_method==='paymongo' ? 'Paid online' : 'Cash collected') : ownerUpfrontPayment(b).label }}</span></dd></div></dl>
<div class="upcoming-bottom"><div class="upcoming-next"><strong>{{ paymentException(b) ? 'Payment exception' : b.occupancy_start_issue ? 'Owner action needed' : 'Next step' }}</strong><p>{{ nextStep(b) }}</p><p v-if="b.payment_method==='paymongo' && ownerUpfrontPayment(b).key!=='paid' && b.payment_due_at" class="upcoming-deadline">Payment due {{ ownerTimestamp(b.payment_due_at) }}</p></div><router-link :to="bookingLink(b)" class="upcoming-open">View booking<i class="fa-solid fa-arrow-right" aria-hidden="true"></i></router-link></div>
</article></div>
<footer><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>An eligible stay starts on its booked check-in date. Confirming arrival records that the student has physically moved in.</span></footer>
</section>
</template>
